import * as Effect from "effect/Effect"
import * as Command from "effect/unstable/cli/Command"
import { Spec } from "./spec"
import { Daemon } from "../services/daemon"
import { ChildProcessSpawner } from "effect/unstable/process/ChildProcessSpawner"

// The environment every handler runs in: the daemon connection and the blessed
// child-process spawner. The local database is not part of it: opening it applies
// migrations, so only the `db` handlers provide it, for their own run.
export type HandlerRequirements = Daemon.Service | ChildProcessSpawner

export type Input<Value> =
  Value extends Spec.Node<infer _Name, infer Command, infer _Commands>
    ? Input<Command>
    : Value extends Command.Command<infer _Name, infer Input, infer _Context, infer _Error, infer _Requirements>
      ? Input
      : never

type RuntimeHandler = (input: unknown) => Effect.Effect<void, unknown, HandlerRequirements>
type Loader<Node extends Spec.Any> = () => Promise<{
  default: (input: Input<Node>) => Effect.Effect<void, any, HandlerRequirements>
}>
type ProvidedCommand = Command.Command<string, unknown, unknown, unknown, Daemon.Service>

export type Handlers<Node extends Spec.Any> = keyof Node["commands"] extends never
  ? Loader<Node>
  : { readonly $?: Loader<Node> } & { readonly [Key in keyof Node["commands"]]: Handlers<Node["commands"][Key]> }

interface LazyHandler {
  readonly spec: Command.Command.Any
  readonly load: () => Promise<{ default: RuntimeHandler }>
}

type RuntimeHandlers =
  | (() => Promise<{ default: RuntimeHandler }>)
  | {
      readonly $?: () => Promise<{ default: RuntimeHandler }>
      readonly [key: string]: RuntimeHandlers | (() => Promise<{ default: RuntimeHandler }>) | undefined
    }

export function handler<const Node extends Spec.Any, Error, Requirements>(
  _node: Node,
  run: (input: Input<Node>) => Effect.Effect<void, Error, Requirements>,
) {
  return run
}

export function handlers<const Root extends Spec.Any>(root: Root, handlers: Handlers<Root>) {
  const result: LazyHandler[] = []

  function add(node: Spec.Any, value: RuntimeHandlers) {
    if (typeof value === "function") {
      result.push({ spec: node.spec, load: value as () => Promise<{ default: RuntimeHandler }> })
      return
    }
    if (value.$) result.push({ spec: node.spec, load: value.$ as () => Promise<{ default: RuntimeHandler }> })
    for (const [name, child] of Object.entries(node.commands)) add(child, value[name] as RuntimeHandlers)
  }

  add(root, handlers as RuntimeHandlers)
  return result
}

export function run(commands: Spec.Any, handlers: ReadonlyArray<LazyHandler>, options: { readonly version: string }) {
  return Command.run(provide(commands, handlers), options) as Effect.Effect<void, unknown, Command.Environment>
}

function provide(node: Spec.Any, handlers: ReadonlyArray<LazyHandler>): ProvidedCommand {
  const handler = handlers.find((handler) => handler.spec === node.spec)
  const spec = handler
    ? node.spec.pipe(
        Command.withHandler((input) =>
          Effect.gen(function* () {
            yield* Effect.flatMap(Effect.promise(handler.load), (module) => module.default(input))
          }),
        ),
      )
    : node.spec
  if (!Object.keys(node.commands).length) return spec as ProvidedCommand
  return spec.pipe(
    Command.withSubcommands(Object.values(node.commands).map((child) => provide(child, handlers))),
  ) as ProvidedCommand
}

export * as Runtime from "./runtime"

import { Commands } from "../commands"
import { Runtime } from "../../framework/runtime"
import { Effect } from "effect"
import { Daemon } from "../../services/daemon"

export default Runtime.handler(Commands, () =>
  Effect.gen(function* () {
    const daemon = yield* Daemon.Service
    const transport = yield* daemon.transport()
    const { runTui } = yield* Effect.promise(() => import("../../tui"))
    yield* runTui(transport)
  }),
)

})

const start = Effect.fn("cli.daemon.start")(function* () {
  const existing = yield* healthy().pipe(Effect.option)
  const found = Option.getOrUndefined(existing)
  const compiled = path.basename(process.execPath).replace(/\.exe$/, "") !== "bun"
  if (found?.version === InstallationVersion && compiled) return found.url
  if (found) yield* stopProcess(found).pipe(Effect.ignore)

  const launched = yield* launch(["serve", "--register"])
  const child = launched.child
  const started = launched.started

  return yield* compatible().pipe(
    // A cold daemon start takes up to ~5s on slow hosts (macOS Intel CI), so
    // a retry count would race it. Wait on a deadline; an exited daemon ends it early.
    Effect.retry({
      schedule: Schedule.spaced("50 millis").pipe(Schedule.both(Schedule.during("20 seconds"))),
      while: () => child.exit === undefined,
    }),
    Effect.map((info) => info.url),
    Effect.mapError((error) => new Error(
      `Failed to start server (${child.exit ? `exited ${child.exit}` : error.message}, ${Date.now() - started}ms)`,
    )),
  )
})

// A detached server of this same executable; the caller waits for it to answer. `child.exit` is set if it dies first.
const launch = Effect.fnUntraced(function* (args: ReadonlyArray<string>) {
  const compiled = path.basename(process.execPath).replace(/\.exe$/, "") !== "bun"
  const entrypoint = compiled ? undefined : process.argv[1]
  if (!compiled && entrypoint === undefined) return yield* Effect.fail(new Error("Failed to resolve CLI entrypoint"))
  const started = Date.now()
  const child: { exit?: string } = {}
  yield* Effect.try({
    try: () => {
      const daemon = spawn(process.execPath, [...(entrypoint ? [entrypoint] : []), ...args], {
        detached: true,
        stdio: "ignore",
        windowsHide: true,
      })
      daemon.once("exit", (code, signal) => (child.exit = signal ? `signal=${signal}` : `code=${code}`))
      daemon.unref()
    },
    catch: (cause) => new Error("Failed to start server", { cause }),
  })
  return { child, started }
})

const startOn = Effect.fn("cli.daemon.startOn")(function* (port: number) {
  const url = `http://127.0.0.1:${port}`
  const client = yield* createClient(url).pipe(Effect.mapError((error) => new Error(String(error))))
  const answering = Effect.tryPromise({
    try: () => client.health.get({ signal: AbortSignal.timeout(2_000) }),
    catch: () => new Error("health-unreachable"),
  })
  if (Option.isSome(yield* answering.pipe(Effect.option))) return url
  const launched = yield* launch(["serve", "--hostname", "127.0.0.1", "--port", String(port)])
  yield* answering.pipe(
    Effect.retry({
      schedule: Schedule.spaced("50 millis").pipe(Schedule.both(Schedule.during("20 seconds"))),
      while: () => launched.child.exit === undefined,
    }),
    Effect.mapError(
      () => new Error(`Failed to start server on port ${port} (${launched.child.exit ?? "no answer"}, ${Date.now() - launched.started}ms)`),
    ),
  )
  return url
})

const transport = Effect.fn("cli.daemon.transport")(function* () {
  return { url: yield* start(), headers: ServerAuth.headers({ password: yield* password() }) }
})

const client = Effect.fn("cli.daemon.client")(function* () {
