const SHUTDOWN_GRACE_MS = 2_000

export default Runtime.handler(Commands.commands.serve, (input) => serveForever(input))

export type ServeInput = {
  readonly hostname: string
  readonly port: Option.Option<number>
  readonly register: boolean
  readonly cors?: ReadonlyArray<string>
  /** Runs once the server answers, with the address it bound. */
  readonly onListening?: (address: HttpServer.Address, webRoot: string | undefined) => Effect.Effect<void, unknown, ChildProcessSpawner>
}

/** The directory of the built web UI, when this install has one. */
export function webRoot() {
  return WebUi.resolveRoot([
    process.env.ORCHESTRA_WEB_UI_DIR,
    path.join(path.dirname(process.execPath), "web"),
    path.join(import.meta.dir, "../../../../web/dist"),
  ])
}

export const serveForever = Effect.fn("cli.serve")(function* (input: ServeInput) {
    return yield* Effect.scoped(
      Effect.gen(function* () {
        // The runtime interrupts on SIGTERM and SIGINT and runs the finalizers; this bounds a finalizer that hangs,
        // as the desktop kills its child a few seconds after SIGTERM. SIGHUP and, on Windows, SIGBREAK are not
        // interrupted by the runtime, so the wait at the end of this scope ends on them as well.
        const shutdown = { signal: undefined as NodeJS.Signals | undefined, startedAt: 0 }
        const note = (status: ServeShutdown.Status) => {
          if (!shutdown.signal) return
          const line = ServeShutdown.evidence({
            level: process.env.ORCHESTRA_LOG_LEVEL,
            pid: process.pid,
            signal: shutdown.signal,
            status,
            elapsedMs: Date.now() - shutdown.startedAt,
          })
          if (line) writeSync(2, line)
        }
        // Registered first, so it runs after every other finalizer: the process exits with the signal's code only
        // once the server and its connections are closed.
        yield* Effect.addFinalizer(() =>
          Effect.sync(() => {
            if (!shutdown.signal) return
            note("disposed")
            process.exit()
          }),
        )
        const daemon = yield* Daemon.Service
        // A desktop-owned child gets a per-launch password in env and never touches the daemon's password file.
        const password = process.env.ORCHESTRA_SERVER_PASSWORD || (yield* daemon.password())
        // The password is captured: drop it from the environment so no child (stdio MCP server, LSP, PTY, omni) inherits it.
        // The server authenticates from the value passed to createRoutes, never from env.
        delete process.env.ORCHESTRA_SERVER_PASSWORD
        delete process.env.ORCHESTRA_SERVER_USERNAME
        const root = yield* Effect.promise(() => webRoot())
        // Legacy transcripts on this database are copied to V2 before the server answers: a Session is eligible only
        // while it has no V2 message, so a prompt reaching an old Session first would skip its history forever.
        yield* Effect.gen(function* () {
          const database = yield* Database.Service
          const imported = yield* SessionV2.SessionLegacyImport.run(database.db)
          if (imported > 0) console.log(`imported ${imported} legacy session transcripts`)
        }).pipe(
          Effect.provide(AppNodeBuilder.build(LayerNode.group([Database.node]))),
          Effect.catchCause((cause) => Effect.logError("legacy session import failed", cause)),
        )
        const listening = yield* listen(input.hostname, input.port, password, hosts(), root, input.cors)
        const address = listening.address
        // Closing the server waits for every open connection, and the event stream never ends on its own. Scope
        // finalizers run in reverse, so this drops the connections before the server closes.
        yield* Effect.addFinalizer(() => Effect.sync(() => listening.server.closeAllConnections?.()))
        if (input.register) yield* daemon.register(address)
        console.log(`server listening on ${HttpServer.formatAddress(address)}`)
        if (input.onListening) yield* input.onListening(address, root)
        return yield* ServeShutdown.untilSignal(process, process.platform, (signal) => {
          if (shutdown.signal) return
          shutdown.signal = signal
          shutdown.startedAt = Date.now()
          process.exitCode = ServeShutdown.exitCode(signal)
          note("started")
          setTimeout(() => process.exit(), SHUTDOWN_GRACE_MS).unref()
        })
      }),
    )
})

function listen(hostname: string, port: Option.Option<number>, password: string, host: ReturnType<typeof hosts>, root: string | undefined, cors?: ReadonlyArray<string>) {
  if (Option.isSome(port)) return bind(hostname, port.value, password, host, root, cors)
  const next = (port: number): ReturnType<typeof bind> =>
    bind(hostname, port, password, host, root, cors).pipe(
      Effect.catch((error) => (port === 65_535 || !addressInUse(error) ? Effect.fail(error) : next(port + 1))),
    )
  return next(4096)
}

function bind(hostname: string, port: number, password: string, host: ReturnType<typeof hosts>, root: string | undefined, cors?: ReadonlyArray<string>) {
  const server = createServer()
  return Layer.build(
    HttpRouter.serve(createRoutes({ password, host, webRoot: root, cors }), { disableListenLog: true, disableLogger: true }).pipe(
      Layer.provideMerge(NodeHttpServer.layer(() => server, { port, host: hostname })),
      Layer.provide(AppNodeBuilder.build(LayerNode.group([Credential.node, PermissionSaved.node, ClaudeCodeAccount.node]))),
    ),
  ).pipe(Effect.map((context) => ({ address: Context.get(context, HttpServer.HttpServer).address, server })))
}

// The Dock tools exist only when the desktop that owns this child handed it a Dock channel.
function hosts() {
  return ProductHost.contributions(AppDockSocket.fromEnv())
}

// The omni build step that the compiled CLI shares (apps/cli): which omni build each
// target ships, where its addon and supervisor come from, and the copy next to the binary.
import fs from "fs"
import path from "path"
import { inspectElf, nativeMachines, NATIVE_MACHINES, requireElfLibc } from "./tree-sitter-prebuilds"
import { WorkspacePaths } from "./workspace-paths.ts"

// D-L8/D-L9: the omni build each target ships, as hugr-omni's platform id. A target with `enabled: false` compiles
// with OMNI_ENABLED=false (the legacy spawner) and ships no omni files. Every declared CLI target has a native build.
export const omniTargets: Record<string, { id: string; enabled: boolean }> = {
  "linux-arm64": { id: "linux-arm64-gnu", enabled: true },
  "linux-x64": { id: "linux-x64-gnu", enabled: true },
  "linux-x64-baseline": { id: "linux-x64-gnu", enabled: true },
  "linux-arm64-musl": { id: "linux-arm64-musl", enabled: true },
  "linux-x64-musl": { id: "linux-x64-musl", enabled: true },
  "linux-x64-baseline-musl": { id: "linux-x64-musl", enabled: true },
  "darwin-arm64": { id: "darwin-arm64", enabled: true },
  "darwin-x64": { id: "darwin-x64", enabled: true },
  "darwin-x64-baseline": { id: "darwin-x64", enabled: true },
  "windows-arm64": { id: "win32-arm64-msvc", enabled: true },
  "windows-x64": { id: "win32-x64-msvc", enabled: true },
  "windows-x64-baseline": { id: "win32-x64-msvc", enabled: true },
}

export type OmniFiles = { addon: string; supervisor: string }

/**
 * The omni row for one build (`target` is its name without the package prefix, e.g. `darwin-arm64`) and, when it is
 * enabled, the files it ships. Resolve every build before building any, so a missing artifact fails at once.
 */
export function resolveOmni(input: { name: string; target: string; os: string; single: boolean }) {
  const omni = omniTargets[input.target]
  if (!omni) throw new Error(`${input.name} has no row in omniTargets`)
  if (input.os !== (omni.id.startsWith("win32-") ? "win32" : omni.id.split("-")[0]))
    throw new Error(`OMNI_TARGET_OS_MISMATCH: ${input.target}`)
  const omniFiles = omni.enabled ? omniSources(input.os, omni.id, input.single) : undefined
  if (omniFiles) requireOmniFiles(omniFiles, { os: input.os, arch: omni.id.split("-")[1]!,
    abi: omni.id.endsWith("-musl") ? "musl" : undefined })
  return { omni, omniFiles }
}

/** Ships the addon as hugr_omni.node and the supervisor (executable) in `bin`, next to the binary. */
export function copyOmni(files: OmniFiles | undefined, bin: string) {
  if (!files) return
  fs.copyFileSync(files.addon, `${bin}/hugr_omni.node`)
  const supervisor = `${bin}/${path.basename(files.supervisor)}`
  fs.copyFileSync(files.supervisor, supervisor)
  fs.chmodSync(supervisor, 0o755)
}

// Where the addon and the supervisor for an omni id come from: OMNI_ARTIFACTS=<dir>/<id>/{hugr_omni.node,
// hugr-omni-supervisor[.exe]}, required by every build but --single. A --single build without it takes this checkout's
// native/omni/target/{release,debug}, admitted for the requested CPU/libc. The files ship next to the binary, never embedded: Bun would
// extract an embedded addon to $TMPDIR, where a planted supervisor wins (probe P1).
function omniSources(os: string, id: string, single: boolean): OmniFiles {
  const supervisor = `hugr-omni-supervisor${os === "win32" ? ".exe" : ""}`
  const artifacts = process.env.OMNI_ARTIFACTS
  if (artifacts) {
    const files = {
      addon: path.join(artifacts, id, "hugr_omni.node"),
      supervisor: path.join(artifacts, id, supervisor),
    }
    return files
  }
  if (!single) throw new Error(`OMNI_ARTIFACTS is required: no omni artifacts for ${id} (OMNI_ENABLED target).`)
  const addon =
    ({ darwin: "libhugr_omni_node.dylib", win32: "hugr_omni_node.dll" } as Record<string, string>)[os] ??
    "libhugr_omni_node.so"
  const native = WorkspacePaths.make(import.meta.dirname).domain("omni")
  const found = ["release", "debug"]
    .map((profile) => path.join(native, "target", profile))
    .map((target) => ({ addon: path.join(target, addon), supervisor: path.join(target, supervisor) }))
    .find((files) => fs.existsSync(files.addon) || fs.existsSync(files.supervisor))
  if (!found) throw new Error(`OMNI_LOCAL_COMPANIONS_MISSING: ${id}: native/omni/target/{release,debug}`)
  return found
}

// Admission runs before a producer replaces output. A named local profile is
// not evidence of target CPU/libc, and an incomplete release cannot borrow debug.
export function requireOmniFiles(files: OmniFiles, target: { os: string; arch: string; abi?: string }) {
  const machine = NATIVE_MACHINES[`${target.os}-${target.arch}`]
  if (machine === undefined || (target.abi !== undefined && (target.os !== "linux" || target.abi !== "musl")))
    throw new Error(`OMNI_TARGET_UNSUPPORTED: ${target.os}-${target.arch}-${target.abi ?? "default"}`)
  for (const kind of ["addon", "supervisor"] as const) {
    const file = files[kind]
    if (typeof file !== "string" || !file) throw new Error(`OMNI_COMPANION_MISSING_OR_NOT_REGULAR: ${kind}`)
    const stat = fs.lstatSync(file, { throwIfNoEntry: false })
    if (!stat?.isFile() || stat.isSymbolicLink() || !stat.size)
      throw new Error(`OMNI_COMPANION_MISSING_OR_NOT_REGULAR: ${kind}: ${file}`)
    if (!nativeMachines(file).includes(machine)) throw new Error(`OMNI_COMPANION_CPU_MISMATCH: ${kind}: ${file}`)
    const bytes = fs.readFileSync(file)
    if (target.os === "linux") {
      const elf = inspectElf(file)
      if (elf.machine !== machine) throw new Error(`OMNI_COMPANION_CPU_MISMATCH: ${kind}: ${file}`)
      const libc = target.abi === "musl" ? "musl" : "glibc"
      if (kind === "addon") requireElfLibc(file, libc)
      if (kind === "supervisor" && (elf.interpreter !== undefined || elf.needed.length)) {
        requireElfLibc(file, libc)
        const loader = libc === "musl" ? `/lib/ld-musl-${target.arch === "x64" ? "x86_64" : "aarch64"}.so.1` :
          target.arch === "x64" ? "/lib64/ld-linux-x86-64.so.2" : "/lib/ld-linux-aarch64.so.1"
